/**
 * Module declaration for `@wails-bindings`.
 *
 * The Vite/Vitest alias maps this specifier to the file generated by
 * `wails3 generate bindings -ts` (wails/frontend/bindings/droidgear-wails/
 * internal/app/app.ts). That generated file lives outside the TypeScript
 * project (tsconfig includes only `src/`), so its exact shape is not
 * re-declared here; `commands.ts` casts the namespace to a method registry
 * and selects Go service methods by name.
 *
 * `pty.ts`, `opener.ts` and `fonts.ts` import their commands directly, so
 * those are declared with the generated signatures.
 */
declare module '@wails-bindings' {
  export interface PtyStartOptions {
    file: string
    args: string[] | null
    name: string | null
    cols: number | null
    rows: number | null
    cwd: string | null
    env: Record<string, string | undefined> | null
  }

  export function PtyStart(opts: PtyStartOptions): Promise<number>
  export function PtyWrite(id: number, data: string): Promise<void>
  export function PtyResize(
    id: number,
    cols: number,
    rows: number
  ): Promise<void>
  export function PtyKill(id: number): Promise<void>

  // Opener service (shell/opener.ts → internal/app/opener.go).
  export function OpenUrl(url: string): Promise<void>
  export function OpenPath(path: string): Promise<void>
  export function RevealItemInDir(item: string): Promise<void>

  // System fonts (shell/fonts.ts → internal/app/fonts.go).
  // Mirrors the Go SystemFont struct returned by GetSystemFonts.
  export interface SystemFont {
    id: string
    name: string
    fontName: string
    path: string
    weight: number
    style: 'normal' | 'italic' | 'oblique'
    monospaced: boolean
  }
  export function GetSystemFonts(): Promise<SystemFont[]>
}
